from fastapi import FastAPI, Request
import sqlite3

app = FastAPI()
conn = sqlite3.connect("production.db", check_same_thread=False)

@app.get("/api/search")
def search_records(query: str, status: str = "active"):
    cursor = conn.cursor()
    # CRITICAL VULNERABILITY: Direct f-string SQL interpolation
    sql = f"SELECT id, title, data FROM records WHERE status = '{status}' AND title LIKE '%{query}%'"

    try:
        cursor.execute(sql)
        records = cursor.fetchall()
        return {"count": len(records), "results": records}
    except Exception as e:
        # Leaking internal database error traceback
        return {"error": str(e), "debug_query": sql}
